// src/tools/registry.ts
function registerAllTools(mcp, ctx) {
  const tools = [
    pingToolDef,
    ...statusTools,
    ...setupTools,
    ...dbTools,
    ...allowOnceTools,
    ...debugTools,
    ...configTools
  ];
  mcp.setRequestHandler(ListToolsRequestSchema, async () => ({
    tools: tools.map((t) => ({
      name: t.name,
      description: t.description,
      inputSchema: t.inputSchema
    }))
  }));
  mcp.setRequestHandler(CallToolRequestSchema, async (request) => {
    const tool = tools.find((t) => t.name === request.params.name);
    if (!tool) {
      throw new McpError(
        ErrorCode.InvalidParams,
        `Unknown tool: ${request.params.name}`
      );
    }
    const result = await tool.handler(request.params.arguments, ctx);
    return { content: result.content };
  });
}

// src/index.ts
import { join as join11 } from "node:path";
import { tmpdir as tmpdir2 } from "node:os";
import { fileURLToPath } from "node:url";
async function main() {
  const sessionId = process.env.CLAUDE_GATE_SESSION_ID ?? `pid-${process.pid}`;
  const socketDir = join11(tmpdir2(), "claude-gate");
  const { mkdirSync: mkdirSync8 } = await import("node:fs");
  mkdirSync8(socketDir, { recursive: true });
  const socketPath = join11(socketDir, `${sessionId}.sock`);
  const projectRoot = process.env.CLAUDE_PROJECT_DIR ?? process.cwd();
  const pluginRoot = process.env.CLAUDE_PLUGIN_ROOT ?? fileURLToPath(new URL("../../", import.meta.url));
  const rulesDir = join11(pluginRoot, "rules");
  const bootstrap = createBootstrap({
    projectRoot,
    sessionId,
    rulesDir
  });
  const pendingActions = new PendingActionStore();
  const ipc = await startIpcServer({ socketPath, bootstrap, pendingActions });
  info(`IPC ready at ${socketPath}`);
  writeActiveSession({
    socket_path: socketPath,
    session_id: sessionId,
    project_root: projectRoot,
    started_at_ms: Date.now()
  });
  const mcp = new Server(
    { name: "claude-gate", version: "0.0.1" },
    { capabilities: { tools: {} } }
  );
  registerAllTools(mcp, { bootstrap, pendingActions });
  const transport = new StdioServerTransport();
  await mcp.connect(transport);
  info("MCP server connected to stdio transport");
  const shutdown = async (signal) => {
    info(`received ${signal}, shutting down`);
    clearActiveSession();
    bootstrap.close();
    await ipc.close();
    process.exit(0);
  };
  process.on("SIGINT", () => void shutdown("SIGINT"));
  process.on("SIGTERM", () => void shutdown("SIGTERM"));
}
main().catch((e) => {
  err("fatal", e);
  process.exit(1);
});
